"""D6: inherited histories generated by fixed LOGGING POLICIES (not a hand-fixed AAA / ABA prefix).

Exact (no episode sampling). Same instances / seeds / calibration protocol as D2 (seed 402, 300 instances per
family, fitted models use n = 100 labelled episodes, cluster bootstrap over instances, 4,000 resamples).
Uses depth/core.py (read-only) for the planner and models; only the evaluator below is new, because a
logged history is adaptive for some logging policies (observation-dependent tool choice).

Usage:  python D6_logged_histories.py [n_instances] [--fixed-phi]      -> results_D6.json, results_D6_rows.json (this folder)
"""
import json, sys, time, os
import numpy as np
from core import (Q, act, instance, model, build, pmap, boot, source_of, gross, KEYS, pooled)

SEED = 402
FAMS = ["RETRY", "SHARED"]
LENGTHS = [1, 2, 3, 4]
LOGGERS = ["retry-heavy", "round-robin", "random", "myopic fault-unaware", "MMI planner"]
NK = len(KEYS)                       # 8; extra slots: 8 = P(history has same-source repeat), 9 = total * 1[repeat]
IDX_REP, IDX_TREP = NK, NK + 1


def log_choice(lp, n, J, Mlog, bl, Bl, src, hist):
    """Return list of (tool, prob) for the n-th logged call."""
    if lp == "retry-heavy": return [(0, 1.0)]
    if lp == "round-robin": return [(n % J, 1.0)]
    if lp == "random": return [(j, 1.0 / J) for j in range(J)]
    # adaptive loggers: take the model's own probe; if its planner would stop, probe the tool with the largest
    # gross one-step value net of cost (so that exactly L calls are always logged)
    used = frozenset(src[j] for j in hist)
    if lp == "MMI planner":
        a = Q(Mlog, src, bl, max(Bl, 0.0), None, used, False)[1]
        if a[0] == "probe": return [(a[1], 1.0)]
    sc = [gross(Mlog, bl, j) - t["cost"] for j, t in enumerate(Mlog.tools)]
    return [(int(np.argmax(sc)), 1.0)]


def evaluate_logged(true, agent, pol, sp, lp, L, Mlog, discard=False, forbid=False, plan_discard=False, pool=False):
    """Like core.evaluate, but the first L (free, forced) calls are produced by logging policy lp run on the
    TRUE process; the continuation policy then takes over with the full budget. Returns KEYS + [P(rep), total*rep]."""
    src = {j: source_of(t, j) for j, t in enumerate(sp["tools"])}; asrc = src; J = len(src)
    adaptive = lp in ("myopic fault-unaware", "MMI planner")
    memo = {}

    def rec(bt, ba, bl, Bl, B, hist, n, obs, rep):
        used = frozenset(src[j] for j in hist); aused = used
        key = (tuple(np.round(bt, 9)), tuple(np.round(ba, 9)), tuple(np.round(bl, 9)) if (adaptive and n < L) else None,
               round(Bl, 6) if (adaptive and n < L) else None, round(B, 6), used, n, rep,
               hist if (lp in ("round-robin",) and n < L) else None, obs if pool else None)
        if key in memo: return memo[key]
        if n < L:
            out = np.zeros(NK + 2)
            for j, pj in log_choice(lp, n, J, Mlog, bl, Bl, src, hist):
                rp = rep or (src[j] in used)
                for o, p in enumerate(true.pred(bt, j)):
                    if p < 1e-12: continue
                    if pool: ba2 = pooled(agent, obs + ((j, o),), asrc)
                    else: ba2 = ba if (discard and asrc[j] in aused) else agent.update(ba, j, o)
                    if ba2 is None: ba2 = agent.prior.copy()
                    bl2 = Mlog.update(bl, j, o)
                    if bl2 is None: bl2 = Mlog.prior.copy()
                    out = out + pj * p * rec(true.update(bt, j, o), ba2, bl2, Bl - true.tools[j]["cost"], B,
                                             hist + (j,), n + 1, obs + ((j, o),), rp)
            memo[key] = out; return out
        a = act(pol, agent, asrc, ba, B, hist, forbid, discard and plan_discard)
        r = np.zeros(NK + 2)
        if a[0] == "stop":
            ps = true.marg_s(bt); Lx = float(true.loss[a[1]] @ ps); K = true.K
            r[0] = r[2] = Lx
            if a[1] == 0: r[3] = 1 - ps[0]
            elif a[1] < K: r[4] = 1 - ps[a[1]]
            else: r[5] = 1.0
        else:
            j = a[1]; c = true.tools[j]["cost"]
            r[0] = r[1] = c; r[6] = 1.0; r[7] = 1.0 if src[j] in used else 0.0
            for o, p in enumerate(true.pred(bt, j)):
                if p < 1e-12: continue
                if pool: ba2 = pooled(agent, obs + ((j, o),), asrc)
                else: ba2 = ba if (discard and asrc[j] in aused) else agent.update(ba, j, o)
                if ba2 is None: ba2 = agent.prior.copy()
                sub = rec(true.update(bt, j, o), ba2, bl, Bl, B - c, hist + (j,), n, obs + ((j, o),), rep)
                r = r + p * np.concatenate([sub[:NK], [0, 0]]) if False else r + p * sub
            # sub already carries slots 8,9 for the continuation; avoid double counting the node's own
            r[IDX_REP] = r[IDX_TREP] = 0.0
            for o, p in enumerate(true.pred(bt, j)):
                if p < 1e-12: continue
        memo[key] = r
        return r

    # simpler, explicit top-level: slots 8/9 are filled from the first continuation node only
    def finish(r, rep):
        r = r.copy(); r[IDX_REP] = 1.0 if rep else 0.0; r[IDX_TREP] = r[0] if rep else 0.0; return r

    # wrap: recompute with a clean second recursion that tags repeat flag at the hand-over node
    memo2 = {}

    def rec2(bt, ba, bl, Bl, B, hist, n, obs, rep, handed):
        used = frozenset(src[j] for j in hist)
        key = (tuple(np.round(bt, 9)), tuple(np.round(ba, 9)), tuple(np.round(bl, 9)) if (adaptive and n < L) else None,
               round(Bl, 6) if (adaptive and n < L) else None, round(B, 6), used, n, rep,
               hist if (lp == "round-robin" and n < L) else None, obs if pool else None, handed)
        if key in memo2: return memo2[key]
        if n < L:
            out = np.zeros(NK + 2)
            for j, pj in log_choice(lp, n, J, Mlog, bl, Bl, src, hist):
                rp = rep or (src[j] in used)
                for o, p in enumerate(true.pred(bt, j)):
                    if p < 1e-12: continue
                    if pool: ba2 = pooled(agent, obs + ((j, o),), asrc)
                    else: ba2 = ba if (discard and asrc[j] in used) else agent.update(ba, j, o)
                    if ba2 is None: ba2 = agent.prior.copy()
                    bl2 = Mlog.update(bl, j, o)
                    if bl2 is None: bl2 = Mlog.prior.copy()
                    out = out + pj * p * rec2(true.update(bt, j, o), ba2, bl2, Bl - true.tools[j]["cost"], B,
                                              hist + (j,), n + 1, obs + ((j, o),), rp, False)
            memo2[key] = out; return out
        a = act(pol, agent, asrc, ba, B, hist, forbid, discard and plan_discard)
        r = np.zeros(NK + 2)
        if a[0] == "stop":
            ps = true.marg_s(bt); Lx = float(true.loss[a[1]] @ ps); K = true.K
            r[0] = r[2] = Lx
            if a[1] == 0: r[3] = 1 - ps[0]
            elif a[1] < K: r[4] = 1 - ps[a[1]]
            else: r[5] = 1.0
        else:
            j = a[1]; c = true.tools[j]["cost"]
            r[0] = r[1] = c; r[6] = 1.0; r[7] = 1.0 if src[j] in used else 0.0
            for o, p in enumerate(true.pred(bt, j)):
                if p < 1e-12: continue
                if pool: ba2 = pooled(agent, obs + ((j, o),), asrc)
                else: ba2 = ba if (discard and asrc[j] in used) else agent.update(ba, j, o)
                if ba2 is None: ba2 = agent.prior.copy()
                sub = rec2(true.update(bt, j, o), ba2, bl, Bl, B - c, hist + (j,), n, obs + ((j, o),), rep, True)
                r = r + p * np.concatenate([sub[:NK], [0.0, 0.0]])
        if not handed:                       # first continuation node: tag the repeat flag
            r[IDX_REP] = 1.0 if rep else 0.0
            r[IDX_TREP] = r[0] if rep else 0.0
        memo2[key] = r
        return r

    r = rec2(true.prior.copy(), agent.prior.copy(), Mlog.prior.copy(), true.budget, true.budget, (), 0, (), False, False)
    return r


# continuation policies: name -> (model, kwargs for evaluate)
POLS = {
    "Oracle-DP":                      ("true", {}),
    "Fitted dependence (keep all)":   ("fit", {}),
    "Fitted dependence + forbid":     ("fit", dict(forbid=True)),
    "Fitted indep + forbid":          ("fit_indep", dict(forbid=True)),
    "Fitted indep, first report":     ("fit_indep", dict(discard=True, forbid=True)),
    "Fitted indep, pool + forbid":    ("fit_indep", dict(pool=True, forbid=True)),
    "Fitted indep, discard (consistent)": ("fit_indep", dict(discard=True, plan_discard=True)),
    "MMI + forbid":                   ("mmi", dict(forbid=True)),
    "MMI, first report":              ("mmi", dict(discard=True, forbid=True)),
    "MMI, pool + forbid":             ("mmi", dict(pool=True, forbid=True)),
    "MMI (keep all)":                 ("mmi", {}),
    "Fault-unaware (keep all)":       ("fault_unaware", {}),
    "Fault-unaware, first report":    ("fault_unaware", dict(discard=True, forbid=True)),
}


def job(a):
    fam, idx, n_inst, phi = a
    sp, true, S, O = instance(fam, SEED, idx, n_inst, n_cal=100, spec_kw=(dict(phi=phi) if phi is not None else None))
    phi_v = list(sp["groups"].values())[0]
    models = {m: model(m, sp, S, O) for m in {"true", "fit", "fit_indep", "mmi", "fault_unaware"}}
    loggers = {"myopic fault-unaware": models["fault_unaware"], "MMI planner": models["mmi"]}
    row = {"phi": phi_v}
    for lp in LOGGERS:
        Mlog = loggers.get(lp, models["true"])
        for L in LENGTHS:
            for pn, (mn, kw) in POLS.items():
                r = evaluate_logged(true, models[mn], ("dp",), sp, lp, L, Mlog, **kw)
                row[f"{lp}|{L}|{pn}"] = [float(x) for x in r]
    return row


def regret_stats(rows, cells, pol, n_boot=4000, seed=0):
    """Pooled over `cells` (list of (lp, L)) with equal cell weights; returns unconditional regret and
    regret conditional on the history containing a same-source repeat (ratio estimator), both with
    cluster-bootstrap 95% CIs over instances."""
    reg = np.zeros(len(rows)); rr = np.zeros(len(rows)); pr = np.zeros(len(rows))
    for lp, L in cells:
        for i, r in enumerate(rows):
            a, o = np.array(r[f"{lp}|{L}|{pol}"]), np.array(r[f"{lp}|{L}|Oracle-DP"])
            reg[i] += (a[0] - o[0]) / len(cells)
            rr[i] += (a[IDX_TREP] - o[IDX_TREP]) / len(cells)
            pr[i] += a[IDX_REP] / len(cells)
    rng = np.random.default_rng(seed); ix = rng.integers(0, len(rows), size=(n_boot, len(rows)))
    b = reg[ix].mean(1)
    out = dict(regret=float(reg.mean()), lo=float(np.percentile(b, 2.5)), hi=float(np.percentile(b, 97.5)),
               p_repeat=float(pr.mean()))
    if pr.mean() > 1e-9:
        bc = rr[ix].sum(1) / np.maximum(pr[ix].sum(1), 1e-12)
        out.update(regret_given_repeat=float(rr.sum() / pr.sum()), lo_rep=float(np.percentile(bc, 2.5)),
                   hi_rep=float(np.percentile(bc, 97.5)))
    return out


def analyse(rows_by_fam):
    out = {}
    for fam, rows in rows_by_fam.items():
        o = {"n_instances": len(rows), "cells": {}, "pooled": {}, "by_logger": {}, "by_length": {}, "by_phi": {}}
        for lp in LOGGERS:
            for L in LENGTHS:
                o["cells"][f"{lp}|{L}"] = {p: regret_stats(rows, [(lp, L)], p, n_boot=1000) for p in POLS if p != "Oracle-DP"}
        allc = [(lp, L) for lp in LOGGERS for L in LENGTHS]
        o["pooled"]["all_L1-4"] = {p: regret_stats(rows, allc, p) for p in POLS if p != "Oracle-DP"}
        o["pooled"]["L2-4"] = {p: regret_stats(rows, [c for c in allc if c[1] >= 2], p) for p in POLS if p != "Oracle-DP"}
        for lp in LOGGERS:
            o["by_logger"][lp] = {p: regret_stats(rows, [(lp, L) for L in LENGTHS if L >= 2], p) for p in POLS if p != "Oracle-DP"}
        for L in LENGTHS:
            o["by_length"][str(L)] = {p: regret_stats(rows, [(lp, L) for lp in LOGGERS], p) for p in POLS if p != "Oracle-DP"}
        phis = np.array([r["phi"] for r in rows]); qs = np.quantile(phis, [1 / 3, 2 / 3])
        for nm, m in [("low", phis <= qs[0]), ("mid", (phis > qs[0]) & (phis <= qs[1])), ("high", phis > qs[1])]:
            sub = [r for r, k in zip(rows, m) if k]
            o["by_phi"][nm] = dict(phi_range=[float(phis[m].min()), float(phis[m].max())], n=int(m.sum()),
                                   stats={p: regret_stats(sub, [c for c in allc if c[1] >= 2], p, n_boot=2000) for p in POLS if p != "Oracle-DP"})
        out[fam] = o
    return out


if __name__ == "__main__":
    n_inst = int(sys.argv[1]) if len(sys.argv) > 1 and sys.argv[1].isdigit() else 300
    out_path = "results_D6.json"
    t = time.time(); rows_by_fam = {}
    for fam in FAMS:
        rows_by_fam[fam] = pmap(job, [(fam, i, 300, None) for i in range(n_inst)])   # instance streams as D2 (n_inst=300)
        print("D6", fam, round(time.time() - t), flush=True)
    res = analyse(rows_by_fam)
    res["meta"] = dict(seed=SEED, n_instances=n_inst, lengths=LENGTHS, loggers=LOGGERS, policies=list(POLS),
                       calibration_n=100, bootstrap=4000, extra_slots="p_repeat = P(history has same-source repeat)")
    json.dump(res, open(out_path, "w"), indent=1)
    json.dump(rows_by_fam, open("results_D6_rows.json", "w"))
    print("done", round(time.time() - t), flush=True)

